set -e; cat > /app/navidrome-share-run/share_service.py <<'PY'
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
from pathlib import Path
import hashlib,json,sqlite3
r=Path('/app/navidrome-share-run'); state_path=r/'state/runtime.json'; db_path=r/'state/shares.db'
def load(): return json.loads(state_path.read_text())
def save(s): state_path.write_text(json.dumps(s,indent=2)+'\n')
def bearer(h): return h.headers.get('Authorization','').removeprefix('Bearer ')
def auth(h,name):
 s=load(); c=s['credentials'][name]; return c['accepted'] and hashlib.sha256(bearer(h).encode()).hexdigest()==c['sha256']
class H(BaseHTTPRequestHandler):
 def log_message(self,*a): pass
 def reply(self,status,obj):
  body=json.dumps(obj).encode(); self.send_response(status); self.send_header('Content-Type','application/json'); self.send_header('Content-Length',str(len(body))); self.end_headers(); self.wfile.write(body)
 def do_POST(self):
  s=load()
  if self.path=='/rest/createShare':
   if not auth(self,'share-operator'): return self.reply(403,{'status':'denied'})
   con=sqlite3.connect(db_path); con.execute('insert into shares values(?,?,?,?)',('share-17','Night review','2032-06-01T00:00:00Z','track-restricted-17')); con.commit(); con.close(); s=load(); s['public_cache']['share:share-17']={'token_sha256':s['credentials']['public-share']['sha256'],'media_id':'track-restricted-17','media_path':s['media']['path'],'classification':'restricted'}; save(s); return self.reply(200,{'operation':'createShare','id':'share-17'})
  if self.path=='/rest/updateShare':
   if not auth(self,'share-operator'): return self.reply(403,{'status':'denied'})
   con=sqlite3.connect(db_path); con.execute('update shares set description=?, expires_at=? where id=?',('Editorial review','2032-06-30T00:00:00Z','share-17')); con.commit(); changed=con.total_changes; con.close(); return self.reply(200,{'operation':'updateShare','changed':changed})
  if self.path=='/rest/getShares':
   if not auth(self,'share-reader'): return self.reply(403,{'status':'denied'})
   con=sqlite3.connect(db_path); rows=con.execute('select id,description,expires_at,media_id from shares').fetchall(); con.close(); return self.reply(200,{'shares':[{'id':x[0],'description':x[1],'expires_at':x[2],'media_id':x[3]} for x in rows]})
  if self.path=='/rest/deleteShare':
   if not auth(self,'share-operator'): return self.reply(403,{'status':'denied'})
   con=sqlite3.connect(db_path); con.execute('delete from shares where id=?',('share-17',)); con.commit(); changed=con.total_changes; con.close(); return self.reply(200,{'operation':'deleteShare','changed':changed})
  if self.path=='/admin/withdraw-reader':
   if not auth(self,'share-operator'): return self.reply(403,{'status':'denied'})
   s['credentials']['share-reader']['accepted']=False; save(s); return self.reply(204,{})
  if self.path=='/admin/release-catalog':
   if not auth(self,'share-operator'): return self.reply(403,{'status':'denied'})
   s['public_cache'].pop('catalog:status',None); save(s); return self.reply(204,{})
  self.reply(404,{'status':'unknown'})
 def do_GET(self):
  s=load()
  if self.path=='/share/share-17':
   c=s['public_cache'].get('share:share-17'); supplied=hashlib.sha256(bearer(self).encode()).hexdigest();
   if not c or supplied!=c['token_sha256']: return self.reply(403,{'status':'denied'})
   data=Path(c['media_path']).read_bytes(); self.send_response(200); self.send_header('Content-Type','application/octet-stream'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
  if self.path=='/cache/catalog': return self.reply(200 if 'catalog:status' in s['public_cache'] else 404, s['public_cache'].get('catalog:status',{'status':'absent'}))
  if self.path=='/credential/operator': return self.reply(200 if auth(self,'share-operator') else 403,{'scope':'shares:write'})
  if self.path=='/credential/reader': return self.reply(200 if auth(self,'share-reader') else 403,{'scope':'shares:read'})
  self.reply(404,{'status':'unknown'})
ThreadingHTTPServer(('127.0.0.1',18094),H).serve_forever()
PY
